using Wms.Common;
using Wms.Domain.Enums;

namespace Wms.Domain;

public sealed class LicensePlateNumber
{
    private readonly List<LicensePlateNumberItem> _items = [];
    private readonly List<LicensePlateNumberPutaway> _putaways = [];
    private LicensePlateNumber() { }
    internal LicensePlateNumber(Guid batchId) { Id = Guid.NewGuid(); BatchId = batchId; }
    public Guid Id { get; private set; }
    public Guid BatchId { get; private set; }
    // Generated by SQL Server from the global, non-cycling sequence on insert.
    public string Code { get; private set; } = null!;
    public LicensePlateNumberBatch Batch { get; private set; } = null!;
    public Guid? ReceivingOrderId { get; private set; }
    public ReceivingOrder? ReceivingOrder { get; private set; }
    public Guid? ReceivingCycleId { get; private set; }
    public ReceivingCycle? ReceivingCycle { get; private set; }
    public Guid? OriginalReceivingLocationId { get; private set; }
    public StorageLocation? OriginalReceivingLocation { get; private set; }
    public LicensePlateNumberStatus Status { get; private set; }
    public string? CreatedBy { get; private set; }
    public string? ResponsibleUserId { get; private set; }
    public DateTimeOffset? CreatedAtUtc { get; private set; }
    public string? CancelledBy { get; private set; }
    public DateTimeOffset? CancelledAtUtc { get; private set; }
    public string? ClosedBy { get; private set; }
    public DateTimeOffset? ClosedAtUtc { get; private set; }
    public long OperationalRevision { get; private set; }
    public IReadOnlyCollection<LicensePlateNumberItem> Items => _items;
    public IReadOnlyCollection<LicensePlateNumberPutaway> Putaways => _putaways;

    public OperationResult AssignReceiving(
        ReceivingCycle cycle, string userId, DateTimeOffset createdAtUtc)
    {
        if (cycle is null || cycle.StartedAtUtc is null || cycle.CompletedAtUtc is not null
            || cycle.ReceivingLocationId is null)
            return OperationError.Invalid("Для LPN нужен действующий цикл с местом приёмки.");

        if (Status != LicensePlateNumberStatus.Available || ReceivingOrderId is not null)
            return OperationError.Conflict("Этикетка уже связана с LPN.");
        if (string.IsNullOrWhiteSpace(userId) || createdAtUtc == default)
            return OperationError.Invalid("Для LPN обязательны ответственный и время создания.");

        ReceivingOrderId = cycle.ReceivingOrderId;
        ReceivingCycleId = cycle.Id;
        OriginalReceivingLocationId = cycle.ReceivingLocationId;
        Status = LicensePlateNumberStatus.Open;
        CreatedBy = userId.Trim();
        ResponsibleUserId = userId.Trim();
        CreatedAtUtc = createdAtUtc;
        OperationalRevision++;
        return OperationResult.Success();
    }

    public OperationResult CancelOpen(string userId, DateTimeOffset cancelledAtUtc, bool canManage)
    {
        if (Status != LicensePlateNumberStatus.Open)
            return OperationError.Invalid("Отменить можно только открытый LPN.");
        if (string.IsNullOrWhiteSpace(userId) || cancelledAtUtc == default)
            return OperationError.Invalid("Для отмены LPN обязательны пользователь и время.");
        if (!canManage && !string.Equals(ResponsibleUserId, userId, StringComparison.Ordinal))
            return OperationError.Conflict("Отменить LPN может ответственный сотрудник или менеджер.");

        Status = LicensePlateNumberStatus.Cancelled;
        CancelledBy = userId.Trim();
        CancelledAtUtc = cancelledAtUtc;
        OperationalRevision++;
        return OperationResult.Success();
    }

    public OperationResult SetReceivingItem(
        Guid stockKeepingUnitId, DateOnly? expirationDate, decimal quantity,
        string userId, DateTimeOffset occurredAtUtc, bool canManage)
    {
        var access = ValidateEditing(userId, canManage);
        if (!access.IsSuccess)
            return access;
        if (stockKeepingUnitId == Guid.Empty)
            return OperationError.Invalid("SKU для позиции LPN обязателен.");
        var validation = LicensePlateNumberItem.Validate(quantity, occurredAtUtc, userId);
        if (!validation.IsSuccess)
            return validation;

        var activeItems = _items.Where(x => !x.IsDeleted).Take(2).ToList();
        if (activeItems.Count > 1)
            return OperationError.Conflict("Приёмный LPN содержит несколько активных позиций.");
        var active = activeItems.SingleOrDefault();
        if (active is not null && active.StockKeepingUnitId != stockKeepingUnitId)
        {
            var deletion = active.Delete(occurredAtUtc, userId);
            if (!deletion.IsSuccess)
                return deletion;
            active = null;
        }

        if (active is null)
            _items.Add(new LicensePlateNumberItem(
                Id, stockKeepingUnitId, expirationDate, quantity, occurredAtUtc, userId.Trim()));
        else
        {
            var update = active.SetQuantityAndExpiration(quantity, expirationDate, occurredAtUtc, userId);
            if (!update.IsSuccess)
                return update;
        }

        OperationalRevision++;
        return OperationResult.Success();
    }

    public OperationResult ClearReceivingItem(
        long expectedRevision, string userId, DateTimeOffset occurredAtUtc, bool canManage)
    {
        var access = ValidateEditing(userId, canManage);
        if (!access.IsSuccess)
            return access;
        if (OperationalRevision != expectedRevision)
            return OperationError.Conflict("LPN изменился. Обновите его перед удалением SKU.");
        var activeItems = _items.Where(x => !x.IsDeleted).Take(2).ToArray();
        if (activeItems.Length != 1)
            return OperationError.Conflict("В LPN должен быть один выбранный SKU.");
        var deleted = activeItems[0].Delete(occurredAtUtc, userId);
        if (deleted.IsSuccess)
            OperationalRevision++;
        return deleted;
    }

    public OperationResult CloseReceiving(string userId, DateTimeOffset closedAtUtc, bool canManage)
    {
        if (ReceivingCycleId is null || OriginalReceivingLocationId is null)
            return OperationError.Invalid("Цикл и исходное место приёмки LPN обязательны.");
        var activeItems = _items.Where(x => !x.IsDeleted).Take(2).ToList();
        if (activeItems.Count > 1)
            return OperationError.Conflict("Приёмный LPN содержит несколько активных позиций.");
        var active = activeItems.SingleOrDefault();
        if (active is null || !WarehouseQuantity.IsPositive(active.Quantity))
            return OperationError.Invalid("Закрыть можно только LPN с положительным количеством одного SKU.");
        var access = ValidateEditing(userId, canManage);
        if (!access.IsSuccess)
            return access;
        if (closedAtUtc == default)
            return OperationError.Invalid("Время закрытия LPN обязательно.");
        Status = LicensePlateNumberStatus.Closed;
        ClosedBy = userId.Trim();
        ClosedAtUtc = closedAtUtc;
        OperationalRevision++;
        return OperationResult.Success();
    }

    public OperationResult CorrectClosedReceivingQuantity(
        decimal quantity, string userId, DateTimeOffset occurredAtUtc)
    {
        if (Status != LicensePlateNumberStatus.Closed || ReceivingCycleId is null
            || OriginalReceivingLocationId is null)
            return OperationError.Conflict("Исправить можно только закрытый приёмный LPN.");
        if (_putaways.Count != 0)
            return OperationError.Conflict("После первого размещения количество LPN изменить нельзя.");

        var active = _items.Where(x => !x.IsDeleted).Take(2).ToArray();
        if (active.Length != 1)
            return OperationError.Conflict("Приёмный LPN должен содержать один действующий SKU.");
        if (active[0].Quantity == quantity)
            return OperationError.Invalid("Количество LPN не изменилось.");

        var changed = active[0].SetQuantity(quantity, occurredAtUtc, userId);
        if (changed.IsSuccess)
            OperationalRevision++;
        return changed;
    }

    public OperationResult DeleteClosedReceiving(string userId, DateTimeOffset occurredAtUtc)
    {
        if (Status != LicensePlateNumberStatus.Closed || ReceivingCycleId is null
            || OriginalReceivingLocationId is null)
            return OperationError.Conflict("Удалить можно только закрытый приёмный LPN.");
        if (string.IsNullOrWhiteSpace(userId) || occurredAtUtc == default)
            return OperationError.Invalid("Для удаления LPN обязательны пользователь и время.");

        Status = LicensePlateNumberStatus.Deleted;
        OperationalRevision++;
        return OperationResult.Success();
    }

    public OperationResult<LicensePlateNumberPutaway> CreateReceivingPutaway(
        Guid itemId,
        Guid destinationStorageLocationId,
        decimal quantity,
        Guid inventoryMovementId,
        string userId,
        DateTimeOffset createdAtUtc)
        => CreatePutawayCore(
            itemId, OriginalReceivingLocationId, destinationStorageLocationId,
            quantity, inventoryMovementId, userId, createdAtUtc);

    private OperationResult<LicensePlateNumberPutaway> CreatePutawayCore(
        Guid itemId,
        Guid? sourceStorageLocationId,
        Guid destinationStorageLocationId,
        decimal quantity,
        Guid inventoryMovementId,
        string userId,
        DateTimeOffset createdAtUtc)
    {
        if (Status != LicensePlateNumberStatus.Closed)
            return OperationError.Invalid("Размещать можно только закрытый LPN.");
        if (sourceStorageLocationId is not Guid sourceLocationId)
            return OperationError.Invalid("Исходное место приёмки LPN не сохранено.");

        var item = _items.SingleOrDefault(x => x.Id == itemId && !x.IsDeleted);
        if (item is null)
            return OperationError.NotFound("Строка состава LPN не найдена.");
        if (!WarehouseQuantity.IsPositive(quantity))
            return OperationError.Invalid("Количество размещения должно быть больше нуля.");

        var placedQuantity = _putaways
            .Where(x => x.LicensePlateNumberItemId == itemId)
            .Sum(x => x.Quantity);
        if (quantity > item.Quantity - placedQuantity)
            return OperationError.Conflict("Количество размещения превышает остаток выбранного LPN.");

        var putawayResult = LicensePlateNumberPutaway.Create(
            Guid.NewGuid(), Id, item.Id, item.StockKeepingUnitId,
            item.ExpirationDate, sourceLocationId, destinationStorageLocationId,
            quantity, inventoryMovementId,
            userId, createdAtUtc);
        if (!putawayResult.IsSuccess)
            return putawayResult.Error!;

        _putaways.Add(putawayResult.Value!);
        OperationalRevision++;
        return putawayResult.Value!;
    }

    private OperationResult ValidateEditing(string userId, bool canManage)
    {
        if (Status != LicensePlateNumberStatus.Open)
            return OperationError.Invalid("Изменять можно только открытый LPN.");
        if (string.IsNullOrWhiteSpace(userId))
            return OperationError.Invalid("Пользователь изменения LPN не определён.");
        return canManage || string.Equals(ResponsibleUserId, userId, StringComparison.Ordinal)
            ? OperationResult.Success()
            : OperationError.Conflict("Изменять LPN может ответственный сотрудник или менеджер.");
    }
}
